from pathlib import Path
root=Path(__file__).resolve().parents[2]
html=(root/'edge-ai-guide/index.html').read_text().replace('<head>','<head><base href="'+(root/'edge-ai-guide').as_uri()+'/">')
qa=r'''
<script>
window.addEventListener('load',async()=>{
 setTimeout(()=>{
 const checks=[],failures=[];const assert=(ok,name)=>{(ok?checks:failures).push(name);};
 const change=(id,value)=>{const el=document.getElementById(id);if(!el)throw new Error('Missing '+id);el.value=value;el.dispatchEvent(new Event('change',{bubbles:true}));};
 try{
  switchWorkbenchTab('delivery');const count=deliveryController.getEvaluation().rows.length;
  assert(document.querySelectorAll('[data-pw-available]').length===10,'10 explicit organization availability controls');
  document.getElementById('pw-role-hw').click();assert(deliveryController.getEvaluation().rows.length===count,'missing roles preserve all tasks');assert(deliveryController.getEvaluation().gaps>0,'missing hardware creates responsibility gaps');
  change('pw-route-hw','merge:sw');assert(deliveryController.getEvaluation().merged>0,'cross-function assignment reaches tasks');
  assert(document.querySelectorAll('.pw-owner.merge').length>0,'mixed-role visual badges');
  document.getElementById('pw-role-qa').click();change('pw-route-qa','si');assert(deliveryController.getEvaluation().gaps>0,'unnamed SI remains unresolved');change('pw-si-qa','Acme validation');assert(deliveryController.getEvaluation().rows.find(t=>t.id==='systemtest').assignments[0].valid,'named SI resolves R');
  document.getElementById('pw-phase-pvt').click();assert(deliveryController.getState().selectedPhase==='pvt','phase buttons navigate despite hover help');document.getElementById('pw-phase-evt').click();document.querySelector('[data-pw-task=prototype]').click();change('pw-status-prototype','done');assert(!deliveryController.getEvaluation().rows.find(t=>t.id==='prototype').complete,'done without evidence cannot pass');change('pw-evidence-prototype','Report EVT-01; reviewer Alex; 2026-10-15');assert(deliveryController.getEvaluation().rows.find(t=>t.id==='prototype').complete,'assigned task with evidence counts as entered acceptance');assert(!deliveryController.getEvaluation().phases.find(p=>p.id==='evt').passed,'predecessors and other work still block stage');document.getElementById('pw-close').click();change('pw-route-hw','merge:fw');assert(deliveryController.getState().progress.prototype.status==='review','responsibility transfer invalidates prior acceptance');
  document.getElementById('pw-role-pm').click();assert(deliveryController.getEvaluation().rows.every(t=>!t.a),'missing PM does not silently reassign A');change('pw-a-evt','exec');assert(deliveryController.getEvaluation().rows.filter(t=>t.phase==='evt').every(t=>t.a==='exec'),'phase A is explicit internal owner');
  const before=JSON.stringify(deliveryController.getState());change('language','en');assert(JSON.stringify(deliveryController.getState())===before,'language switch preserves workflow state');assert(document.querySelector('.pw-context').innerText.includes('APPLICATION'),'English workflow content');
  const snapshotKey=deliveryController.getState().snapshot.key;switchWorkbenchTab('selection');params.inferFps=20;refreshEvaluation();switchWorkbenchTab('delivery');assert(deliveryController.getState().snapshot.key!==snapshotKey,'assessment automatically regenerates workflow');assert(!deliveryController.getState().available.hw&&!deliveryController.getState().available.qa,'automatic refresh preserves team availability');assert(deliveryController.getState().routes.qa.partner==='Acme validation','automatic refresh preserves SI arrangement');
  assert(document.querySelectorAll('.pw-flow-node').length===8,'all stages have equal workflow nodes');assert(document.querySelector('.pw-flow-node.has-gap .pw-missing'),'absent roles flagged on workflow');assert(document.querySelectorAll('.pw-photon').length===9,'dependency and feedback flow animated');document.querySelector('[data-pw-action=motion]').click();assert(document.querySelector('.pw-paused'),'animation can pause');
  const beforeTasks=deliveryController.getEvaluation().rows.length;params.cameraPlatform='drone';refreshEvaluation();assert(deliveryController.getEvaluation().rows.some(t=>t.id==='control')&&deliveryController.getEvaluation().rows.some(t=>t.id==='optics'),'moving camera regenerates application-specific tasks');assert(deliveryController.getEvaluation().rows.length>beforeTasks&&!deliveryController.getState().available.hw,'new application work retains missing hardware role');
  change('pw-raci-status-bringup','active');assert(deliveryController.getEvaluation().rows.find(t=>t.id==='bringup').status==='active','RACI edits task status directly');assert(document.querySelector('[data-pw-node="evt"] .pw-phase-status').textContent.includes('In progress'),'flow shows task activity not headcount');assert(document.querySelector('[data-pw-node="evt"]').classList.contains('pw-linked'),'edited task highlights its flow stage');const roleTag=document.querySelector('[data-pw-node="evt"] [data-pw-help][role=button]');roleTag.dispatchEvent(new Event('pointerover',{bubbles:true}));assert(document.getElementById('pw-tooltip').textContent.includes('not necessarily a separate job'),'role hover explains functional responsibility');assert(document.getElementById('pw-role-fw').parentElement.textContent.includes('FW'),'team labels match FW abbreviation');
  assert(document.getElementById('pw-role-cloud').disabled,'unused Cloud is not applicable, no staffing required');pool.add('llm');params.llmPlacement='cloud';refreshEvaluation();assert(!document.getElementById('pw-role-cloud').disabled,'cloud API activates Cloud function');change('pw-applicability-cloud','na');assert(document.querySelector('.pw-conflict'),'incompatible not-needed choice opens conflict dialog');assert(deliveryController.getEvaluation().applicabilityConflicts.includes('cloud'),'unresolved applicability conflict retained');document.querySelector('[data-pw-action=local]').click();assert(params.llmPlacement==='local'&&params.decisionPlacement==='local'&&pool.has('private'),'confirmed local option updates assessment requirements');assert(!deliveryController.getEvaluation().rows.some(t=>t.id==='cloudapi'),'cloud integration removed after local switch');assert(!deliveryController.getState().available.hw,'local linkage preserves team configuration');params.llmPlacement='cloud';refreshEvaluation();assert(document.querySelector('.pw-conflict'),'later cloud requirement reopens not-applicable conflict');document.querySelector('[data-pw-action=keep-role]').click();assert(deliveryController.getState().rolePolicy.cloud==='auto','keep requirement restores applicability');
  const csv=deliveryController.csv();assert(csv.includes('Acme validation')&&csv.includes('prototype'),'CSV contains resolved owners and tasks');
  const svg=document.querySelector('.pw-sankey svg').outerHTML;assert(!new DOMParser().parseFromString(svg,'image/svg+xml').querySelector('parsererror'),'routing SVG parses');
  assert(document.documentElement.scrollWidth<=innerWidth,'no page-level horizontal overflow');
  assert(!document.querySelector('.pw-drawer'),'task details closed');
 }catch(e){failures.push(String(e.stack||e));}
 const result={checks:checks.length,failures,width:innerWidth,scrollWidth:document.documentElement.scrollWidth};
 if(location.search.includes('report')){document.head.innerHTML='<title>Product Flow QA</title>';document.body.innerHTML='<pre data-own-locale="true" id="qa-result"></pre>';document.getElementById('qa-result').textContent=JSON.stringify(result,null,2);}
 else{document.getElementById('pw-role-pm')?.click();document.querySelector('.pw-organization').open=false;window.scrollTo(0,0);const status=document.createElement('div');status.textContent=JSON.stringify(result);status.style.cssText='position:fixed;bottom:0;left:0;z-index:100;background:white;font:10px monospace;padding:4px';document.body.append(status);if(location.search.includes('flow'))document.querySelectorAll('.topbar,.workbench-tabs,.pw-context,.pw-organization,.pw-scope,.pw-summary,.pw-lifecycle,.pw-stage,.pw-notice').forEach(n=>n.style.display='none');}
},300);});
</script>'''
html=html.replace('</body>',qa+'</body>')
Path('/tmp/product-flow-browser-qa.html').write_text(html)
